#!/usr/bin/env bash
# Render the Grit app icon for desktop notifications.
#
# The tile itself is generated by apps/mobile/scripts/make-tile-svgs.py, which
# stays the single source of truth for the mark and its lighting. All this does
# is rasterise that SVG at the size a freedesktop notification actually draws
# (48px typically, 256 gives every server headroom to scale down cleanly).
#
# The PNG lands next to the QML that uses it, because services/grit is
# symlinked into the shell, so the icon travels with the repo instead of having
# to be installed into the shell's own assets directory.
#
# Needs rsvg-convert (librsvg).
set -euo pipefail
cd "$(dirname "$0")/.."

SRC=../mobile/assets/icon-tile.svg
OUT=services/grit/grit-icon.png

rsvg-convert -w 256 -h 256 "$SRC" -o "$OUT"
echo "wrote apps/panel/$OUT"
